use std::{
    ffi::{CStr, CString},
    os::raw::c_char,
    ptr::NonNull,
};

use crate::errors::{Error, ErrorType, Result};

// Generated by bindgen - silence its warnings without hiding ours
#[allow(
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    dead_code,
    unused_imports,
    clippy::all
)]
mod ffi {
    include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
}

pub use ffi::*;

// =============================================================================
// Utilities
// =============================================================================

fn rstocstr(fname: &str) -> Result<CString> {
    // convert fname to a c string fname
    CString::new(fname)
        .map_err(|_| Error::new(ErrorType::InvalidArgument, "Expected valid filename"))
}

/// Turns an error message that numstore copied for us into a String, and
/// frees the copy. None when there was no error to take.
unsafe fn take_errstr(ptr: *const c_char) -> Option<String> {
    if ptr.is_null() {
        return None;
    }
    let msg = CStr::from_ptr(ptr).to_string_lossy().into_owned();
    free(ptr as *mut std::os::raw::c_void);
    Some(msg)
}

// What a failed call reports when there is no message to take
const NO_MESSAGE: &str = "numstore operation failed";

pub struct CBuf {
    ptr: NonNull<u8>,
    len: usize,
}

extern "C" {
    fn free(ptr: *mut std::os::raw::c_void);
}

impl CBuf {
    pub unsafe fn from_raw(ptr: NonNull<std::os::raw::c_void>, len: b_size) -> CBuf {
        CBuf {
            ptr: ptr.cast(),
            len: len as usize,
        }
    }
}

impl std::ops::Deref for CBuf {
    type Target = [u8];

    fn deref(&self) -> &[u8] {
        unsafe { std::slice::from_raw_parts(self.ptr.as_ptr(), self.len) }
    }
}

impl Drop for CBuf {
    fn drop(&mut self) {
        unsafe { free(self.ptr.as_ptr().cast()) };
    }
}

// =============================================================================
// Rust-ifying native c functions
// Writing similar functions in rust for C counter parts
// =============================================================================

pub fn rs_ns_open(fname: &str) -> Result<NonNull<nsdb_t>> {
    // Error buffer to capture c error
    // We assume the c function appends a NULL terminator
    let mut err_msg = [0u8; 512];

    // Run the c function
    let handle = unsafe {
        let path = rstocstr(fname)?;
        let erstr = err_msg.as_mut_ptr().cast::<std::os::raw::c_char>();
        let elen = err_msg.len() as u32;
        ns_open_with_error(path.as_ptr(), erstr, elen)
    };

    // Convert errors to rust
    NonNull::new(handle).ok_or_else(|| {
        let msg = CStr::from_bytes_until_nul(&err_msg)
            .expect("ns_open_with_error NULL terminates erstr")
            .to_string_lossy()
            .into_owned();

        Error::new(ErrorType::IoErr, msg)
    })
}

pub fn rs_ns_cleanup(fname: &str) -> Result<()> {
    let ret = unsafe {
        let path = rstocstr(fname)?;
        ns_cleanup(path.as_ptr())
    };

    if ret < 0 {
        Err(Error::new(
            ErrorType::IoErr,
            format!("Failed to clean up database: {}", fname),
        ))
    } else {
        Ok(())
    }
}

pub fn rs_ns_close(db: NonNull<nsdb_t>) -> Result<()> {
    let ret = unsafe { ns_close(db.as_ptr()) };

    if ret < 0 {
        Err(Error::new(ErrorType::IoErr, "Failed to close database"))
    } else {
        Ok(())
    }
}

/// Variable

pub fn rs_ns_var_len(var: NonNull<nsdb_var_t>) -> b_size {
    unsafe { ns_var_len(var.as_ptr()) }
}

pub fn rs_ns_var_free(var: NonNull<nsdb_var_t>) {
    unsafe { ns_var_free(var.as_ptr()) };
}

/// Error Handling

// A failed call leaves its error on the database until someone takes it.
// These always ask for a copy (the message inside the database can be
// overwritten by the next failure), turn it into a String and free it.

pub fn rs_ns_strerror(db: NonNull<nsdb_t>) -> String {
    unsafe { take_errstr(ns_strerror(db.as_ptr(), true)) }.unwrap_or_else(|| NO_MESSAGE.into())
}

pub fn rs_ns_plan_strerror(plan: NonNull<nsdb_plan_t>) -> String {
    unsafe { take_errstr(ns_plan_strerror(plan.as_ptr(), true)) }
        .unwrap_or_else(|| NO_MESSAGE.into())
}

/// Transactions

pub fn rs_ns_begin(db: NonNull<nsdb_t>) -> Result<NonNull<nsdb_txn_t>> {
    let handle = unsafe { ns_begin(db.as_ptr()) };
    NonNull::new(handle).ok_or_else(|| {
        let msg = rs_ns_strerror(db);
        Error::new(ErrorType::IoErr, msg)
    })
}

pub fn rs_ns_commit(db: NonNull<nsdb_t>, tx: NonNull<nsdb_txn_t>) -> Result<()> {
    let ret = unsafe { ns_commit(db.as_ptr(), tx.as_ptr()) };

    if ret < 0 {
        Err(Error::new(ErrorType::IoErr, rs_ns_strerror(db)))
    } else {
        Ok(())
    }
}

pub fn rs_ns_rollback(db: NonNull<nsdb_t>, tx: NonNull<nsdb_txn_t>) -> Result<()> {
    let ret = unsafe { ns_rollback(db.as_ptr(), tx.as_ptr()) };

    if ret < 0 {
        Err(Error::new(ErrorType::IoErr, rs_ns_strerror(db)))
    } else {
        Ok(())
    }
}

/// Plans

pub fn rs_ns_plan_create(db: NonNull<nsdb_t>, query: &str) -> Result<NonNull<nsdb_plan_t>> {
    let query = rstocstr(query)?;

    // Pass the query through "%s" so it is never interpreted as a format
    let handle = unsafe { ns_plan_fcreate(db.as_ptr(), c"%s".as_ptr(), query.as_ptr()) };

    NonNull::new(handle).ok_or_else(|| Error::new(ErrorType::IoErr, rs_ns_strerror(db)))
}

pub fn rs_ns_plan_free(plan: NonNull<nsdb_plan_t>) {
    unsafe { ns_plan_free(plan.as_ptr()) };
}

pub fn rs_ns_plan_execute(
    plan: NonNull<nsdb_plan_t>,
    tx: Option<NonNull<nsdb_txn_t>>,
) -> Result<()> {
    let ret = unsafe {
        let tx = tx.map_or(std::ptr::null_mut(), |p| p.as_ptr());
        ns_plan_execute(plan.as_ptr(), tx)
    };

    if ret < 0 {
        Err(Error::new(ErrorType::IoErr, rs_ns_plan_strerror(plan)))
    } else {
        Ok(())
    }
}

pub fn rs_ns_plan_get_var(
    plan: NonNull<nsdb_plan_t>,
    tx: Option<NonNull<nsdb_txn_t>>,
) -> Result<Option<NonNull<nsdb_var_t>>> {
    let handle = unsafe {
        let tx = tx.map_or(std::ptr::null_mut(), |p| p.as_ptr());
        ns_plan_get_var(plan.as_ptr(), tx)
    };

    if let Some(handle) = NonNull::new(handle) {
        return Ok(Some(handle));
    }

    // NULL with no error is "get if exists" on a missing variable. Every
    // failed call here takes its error, so none is left from an earlier one
    match unsafe { take_errstr(ns_plan_strerror(plan.as_ptr(), true)) } {
        None => Ok(None),
        Some(msg) => Err(Error::new(ErrorType::IoErr, msg)),
    }
}

pub fn rs_ns_plan_read(
    plan: NonNull<nsdb_plan_t>,
    tx: Option<NonNull<nsdb_txn_t>>,
    dest: &mut [u8],
) -> Result<b_size> {
    let ret = unsafe {
        let tx = tx.map_or(std::ptr::null_mut(), |p| p.as_ptr());
        ns_plan_read(
            plan.as_ptr(),
            tx,
            dest.as_mut_ptr().cast(),
            dest.len() as b_size,
        )
    };

    if ret < 0 {
        Err(Error::new(ErrorType::IoErr, rs_ns_plan_strerror(plan)))
    } else {
        Ok(ret as b_size)
    }
}

pub fn rs_ns_plan_write(
    plan: NonNull<nsdb_plan_t>,
    tx: Option<NonNull<nsdb_txn_t>>,
    src: &[u8],
) -> Result<b_size> {
    let ret = unsafe {
        let tx = tx.map_or(std::ptr::null_mut(), |p| p.as_ptr());
        ns_plan_write(plan.as_ptr(), tx, src.as_ptr().cast(), src.len() as b_size)
    };

    if ret < 0 {
        Err(Error::new(ErrorType::IoErr, rs_ns_plan_strerror(plan)))
    } else {
        Ok(ret as b_size)
    }
}

pub fn rs_ns_plan_malloc(
    plan: NonNull<nsdb_plan_t>,
    tx: Option<NonNull<nsdb_txn_t>>,
) -> Result<CBuf> {
    let mut dlen: b_size = 0;
    let handle = unsafe {
        let tx = tx.map_or(std::ptr::null_mut(), |p| p.as_ptr());
        ns_plan_malloc(plan.as_ptr(), tx, &mut dlen)
    };

    match NonNull::new(handle) {
        Some(buf) => Ok(unsafe { CBuf::from_raw(buf, dlen) }),
        None => Err(Error::new(ErrorType::IoErr, rs_ns_plan_strerror(plan))),
    }
}
